    for (i64 i = 0; i < n; ++i)
        for (i64 j = 0; j < n; ++j)
            blk[i][j] = C[i][R-1] * C[j][R-1];

    vector<vector<i64>> tot(n+1, vector<i64>(n+1, 0));
    for (i64 i = 1; i <= n; ++i)
        for (i64 j = 1; j <= n; ++j)
            tot[i][j] = tot[i][j-1] + tot[i-1][j] - tot[i-1][j-1] + blk[i-1][j-1];

    vector<vector<i64>> rev(n+1, vector<i64>(n+1, 0));
    for (i64 i = 0; i <= n; ++i)
        for (i64 j = 0; j <= n; ++j)
            rev[i][j] = tot[n][n] - tot[n-i][n] - tot[n][n-j] + tot[n-i][n-j];

    i64 d = min(2*n-1, n+R);
    vector<vector<map<i64,i64>>> dp(n+1, vector<map<i64,i64>>(n+1));
    vector<vector<map<i64,i64>>> bp(n+1, vector<map<i64,i64>>(n+1));
    dp[0][0][0] = bp[0][0][0] = 1;

    i64 best_val = T[R][C];
    i64 total_sum = tot[n][n];
    i64 m1 = (-best_val + total_sum) / 2;
    i64 m2 = total_sum - m1;
    i64 ans = 0;

    for (i64 x = 0; x <= n; ++x) {
        for (i64 y = 0; y < n; ++y) {
            if (x + y + 1 <= d && s[x + y] != 'B') {
                for (auto &kv : dp[x][y]) {
                    i64 area2 = kv.first + tot[n][y+1] - tot[x][y+1];
                    if (area2 <= m2) dp[x][y+1][kv.first] += kv.second;
                }
            }
            if (x + y + 1 <= 2*n - d && s[n - x + n - y - 1] != 'B') {
                for (auto &kv : bp[x][y]) {
                    i64 area2 = total_sum - kv.first - tot[n-x][n-(y+1)];
                    if (area2 <= m2) bp[x][y+1][kv.first] += kv.second;
                }
            }
        }
        if (x == n) continue;
        for (i64 y = 0; y <= n; ++y) {
            if (x + y + 1 <= d && s[x + y] != 'A') {
                i64 new_area = tot[x+1][y] - tot[x][y];
                for (auto &kv : dp[x][y]) {
                    i64 c = kv.first + new_area;
                    i64 area2 = tot[x+1][n] - c;
                    if (area2 <= m2) dp[x+1][y][c] += kv.second;
                }
            }
            if (x + y + 1 <= 2*n - d && s[n - x + n - y - 1] != 'A') {
                i64 new_area = tot[n-x][n-y] - tot[n-x-1][n-y];
                for (auto &kv : bp[x][y]) {
                    if (kv.first + new_area <= m2) bp[x+1][y][kv.first + new_area] += kv.second;
                }
            }
            if (x + y + 1 <= d) dp[x][y].clear();
            if (x + y + 1 <= 2*n - d) bp[x][y].clear();
        }
    }

    for (i64 x = 0; x <= n; ++x) {
        i64 y = d - x;
        if (y < 0 || y > n) continue;
        for (auto &kv : dp[x][y]) {
            i64 c = kv.first;
            i64 freq = kv.second;
            ans += freq * bp[n-x][n-y][m1 - c];
            if (m1 != m2) ans += freq * bp[n-x][n-y][m2 - c];
        }
    }

    cout << ans << '\n';
    return 0;
}
